-- LILA schema v1 design artifact. Execute only AFTER SQLCipher keying.
-- Python services enforce JSON Schema and state transitions in addition to these constraints.
PRAGMA foreign_keys=ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE accounts(id TEXT PRIMARY KEY, platform TEXT NOT NULL, external_subject TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), UNIQUE(platform,external_subject));
CREATE TABLE content_versions(id TEXT PRIMARY KEY, kind TEXT NOT NULL, canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json)), digest TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), instruction_version TEXT NOT NULL REFERENCES content_versions(id), criteria_version TEXT NOT NULL REFERENCES content_versions(id), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), generation INTEGER NOT NULL CHECK(generation>0), state TEXT NOT NULL CHECK(state IN ('DRAFT','QUEUED','ACTIVE','AWAITING_INPUT','BLOCKED','PAUSED','STOPPED','COMPLETED')), individual_hold INTEGER NOT NULL DEFAULT 0 CHECK(individual_hold IN(0,1)), stop_requested INTEGER NOT NULL DEFAULT 0 CHECK(stop_requested IN(0,1)), revision INTEGER NOT NULL DEFAULT 1, terminal_at TEXT, UNIQUE(task_id,generation));
CREATE UNIQUE INDEX one_live_run_per_task ON runs(task_id) WHERE state NOT IN('STOPPED','COMPLETED');
CREATE TABLE execution_control(id INTEGER PRIMARY KEY CHECK(id=1), global_hold INTEGER NOT NULL CHECK(global_hold IN(0,1)), revision INTEGER NOT NULL);
INSERT INTO execution_control VALUES(1,0,1);
CREATE TABLE jobs(id TEXT PRIMARY KEY, platform TEXT NOT NULL, external_id TEXT, canonical_url TEXT, identity_status TEXT NOT NULL CHECK(identity_status IN('VERIFIED','UNKNOWN','POSSIBLE_DUPLICATE')), metadata_version TEXT REFERENCES content_versions(id));
CREATE UNIQUE INDEX job_external_identity ON jobs(platform,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE job_identity_aliases(platform TEXT NOT NULL, alias TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), PRIMARY KEY(platform,alias));
CREATE TABLE duplicate_reviews(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), job_id TEXT NOT NULL REFERENCES jobs(id), other_job_id TEXT NOT NULL REFERENCES jobs(id), disposition TEXT NOT NULL CHECK(disposition IN('PENDING','SAME','DISTINCT')), revision INTEGER NOT NULL, CHECK(job_id<>other_job_id));
CREATE TABLE candidates(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), job_id TEXT NOT NULL REFERENCES jobs(id), criteria_version TEXT NOT NULL REFERENCES content_versions(id), eligibility TEXT NOT NULL CHECK(eligibility IN('ELIGIBLE','EXCLUDED','REVIEW','SKIPPED')), relevance_version TEXT REFERENCES content_versions(id), UNIQUE(run_id,job_id));
CREATE TABLE applications(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), job_id TEXT NOT NULL REFERENCES jobs(id), effective_outcome TEXT NOT NULL CHECK(effective_outcome IN('NONE','PENDING','CONFIRMED','FAILED','UNCERTAIN','USER_REPORTED')), revision INTEGER NOT NULL DEFAULT 1, UNIQUE(account_id,job_id));
CREATE TABLE facts(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), field_key TEXT NOT NULL, current_version TEXT, UNIQUE(account_id,field_key));
CREATE TABLE fact_versions(id TEXT PRIMARY KEY, fact_id TEXT NOT NULL REFERENCES facts(id), value_version TEXT NOT NULL REFERENCES content_versions(id), source_version TEXT REFERENCES content_versions(id), status TEXT NOT NULL CHECK(status IN('PROPOSED','VERIFIED','STALE','REJECTED')), supersedes_id TEXT REFERENCES fact_versions(id), created_at TEXT NOT NULL);
CREATE TRIGGER fact_head_ownership BEFORE UPDATE OF current_version ON facts WHEN NEW.current_version IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fact_versions WHERE id=NEW.current_version AND fact_id=NEW.id) BEGIN SELECT RAISE(ABORT,'fact version ownership mismatch'); END;
CREATE TRIGGER fact_head_initial BEFORE INSERT ON facts WHEN NEW.current_version IS NOT NULL BEGIN SELECT RAISE(ABORT,'create fact before assigning version'); END;
CREATE TRIGGER fact_head_delete BEFORE DELETE ON fact_versions WHEN EXISTS(SELECT 1 FROM facts WHERE current_version=OLD.id) BEGIN SELECT RAISE(ABORT,'clear current version before retention delete'); END;
CREATE TABLE artifact_versions(id TEXT PRIMARY KEY, document_id TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), object_id TEXT NOT NULL UNIQUE, media_type TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length>=0), digest TEXT NOT NULL, key_id TEXT NOT NULL, wrapped_dek BLOB NOT NULL, readiness TEXT NOT NULL CHECK(readiness IN('STAGING','READY','CORRUPT','DELETING')), created_at TEXT NOT NULL);
CREATE TABLE drafts(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), content_version TEXT NOT NULL REFERENCES content_versions(id), artifact_version TEXT REFERENCES artifact_versions(id), created_at TEXT NOT NULL);
CREATE TABLE draft_facts(draft_id TEXT NOT NULL REFERENCES drafts(id), fact_version_id TEXT NOT NULL REFERENCES fact_versions(id), PRIMARY KEY(draft_id,fact_version_id));
CREATE TABLE policies(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), revision INTEGER NOT NULL, scope_version TEXT NOT NULL REFERENCES content_versions(id), expires_at TEXT NOT NULL, run_cap INTEGER NOT NULL CHECK(run_cap>0), daily_cap INTEGER NOT NULL CHECK(daily_cap>0), timezone TEXT NOT NULL, budget_micro_usd INTEGER CHECK(budget_micro_usd>=0), revoked_at TEXT);
CREATE TABLE policy_versions(policy_id TEXT NOT NULL REFERENCES policies(id), revision INTEGER NOT NULL, snapshot_version TEXT NOT NULL REFERENCES content_versions(id), PRIMARY KEY(policy_id,revision));
CREATE TABLE approvals(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), expires_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('ACTIVE','REJECTED','REVOKED','EXPIRED')), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE actions(id TEXT PRIMARY KEY, logical_step_key TEXT NOT NULL, application_id TEXT NOT NULL REFERENCES applications(id), run_id TEXT NOT NULL REFERENCES runs(id), kind TEXT NOT NULL, payload_version TEXT NOT NULL REFERENCES content_versions(id), draft_id TEXT REFERENCES drafts(id), policy_id TEXT REFERENCES policies(id), policy_revision INTEGER, approval_id TEXT REFERENCES approvals(id), state TEXT NOT NULL CHECK(state IN('PREPARED','WAITING_AUTH','READY','DISPATCH_INTENT','CLAIMED','DISPATCHED','CONFIRMED','FAILED','UNCERTAIN','CANCELED')), generation INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(run_id,logical_step_key), CHECK((policy_id IS NULL)=(policy_revision IS NULL)));
CREATE TABLE approval_members(approval_id TEXT NOT NULL REFERENCES approvals(id), action_id TEXT NOT NULL REFERENCES actions(id), payload_version TEXT NOT NULL REFERENCES content_versions(id), PRIMARY KEY(approval_id,action_id));
CREATE UNIQUE INDEX one_pending_submission ON actions(application_id) WHERE kind='submit_application' AND state IN('DISPATCH_INTENT','CLAIMED','DISPATCHED','UNCERTAIN');
CREATE TABLE submission_guards(application_id TEXT PRIMARY KEY REFERENCES applications(id), action_id TEXT REFERENCES actions(id), reason TEXT NOT NULL CHECK(reason IN('IN_FLIGHT','UNCERTAIN','CONFIRMED','USER_REPORTED')), revision INTEGER NOT NULL);
CREATE TABLE outcomes(id TEXT PRIMARY KEY, action_id TEXT NOT NULL REFERENCES actions(id), outcome TEXT NOT NULL CHECK(outcome IN('CONFIRMED','FAILED','UNCERTAIN','USER_REPORTED')), not_submitted_proven INTEGER NOT NULL DEFAULT 0 CHECK(not_submitted_proven IN(0,1)), provenance TEXT NOT NULL CHECK(provenance IN('SYSTEM','OWNER')), evidence_version TEXT REFERENCES content_versions(id), supersedes_id TEXT REFERENCES outcomes(id), occurred_at TEXT NOT NULL);
CREATE TABLE leases(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), worker_id TEXT NOT NULL, generation INTEGER NOT NULL, expires_at TEXT NOT NULL, fenced INTEGER NOT NULL CHECK(fenced IN(0,1)));
CREATE TABLE budget_windows(id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES policies(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, timezone TEXT NOT NULL, submitted INTEGER NOT NULL DEFAULT 0 CHECK(submitted>=0), reserved_actions INTEGER NOT NULL DEFAULT 0 CHECK(reserved_actions>=0), reserved_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK(reserved_micro_usd>=0), consumed_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK(consumed_micro_usd>=0), UNIQUE(policy_id,starts_at,ends_at));
CREATE TABLE reservations(id TEXT PRIMARY KEY, window_id TEXT NOT NULL REFERENCES budget_windows(id), run_id TEXT NOT NULL REFERENCES runs(id), action_id TEXT REFERENCES actions(id), invocation_id TEXT, amount_micro_usd INTEGER NOT NULL CHECK(amount_micro_usd>=0), state TEXT NOT NULL CHECK(state IN('RESERVED','CONSUMED','UNCERTAIN','RELEASED')), CHECK((action_id IS NOT NULL) <> (invocation_id IS NOT NULL)));
CREATE UNIQUE INDEX action_reservation ON reservations(action_id) WHERE action_id IS NOT NULL;
CREATE UNIQUE INDEX invocation_reservation ON reservations(invocation_id) WHERE invocation_id IS NOT NULL;
CREATE TABLE run_counters(run_id TEXT NOT NULL REFERENCES runs(id), policy_id TEXT NOT NULL REFERENCES policies(id), submitted INTEGER NOT NULL DEFAULT 0, reserved INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(run_id,policy_id), CHECK(submitted>=0 AND reserved>=0));
CREATE TABLE ai_invocations(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), config_version TEXT NOT NULL REFERENCES content_versions(id), request_digest TEXT NOT NULL, reservation_id TEXT NOT NULL REFERENCES reservations(id), state TEXT NOT NULL, response_version TEXT REFERENCES content_versions(id), input_tokens INTEGER, output_tokens INTEGER, cost_micro_usd INTEGER, provider_request_id TEXT);
CREATE TABLE checkpoints(run_id TEXT NOT NULL REFERENCES runs(id), namespace TEXT NOT NULL, checkpoint_id TEXT NOT NULL, parent_id TEXT, generation INTEGER NOT NULL, checkpoint_json TEXT NOT NULL CHECK(json_valid(checkpoint_json)), metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)), new_versions_json TEXT NOT NULL CHECK(json_valid(new_versions_json)), PRIMARY KEY(run_id,namespace,checkpoint_id));
CREATE TABLE checkpoint_writes(run_id TEXT NOT NULL, namespace TEXT NOT NULL, checkpoint_id TEXT NOT NULL, task_id TEXT NOT NULL, write_index INTEGER NOT NULL, task_path TEXT NOT NULL, channel TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), PRIMARY KEY(run_id,namespace,checkpoint_id,task_id,write_index), FOREIGN KEY(run_id,namespace,checkpoint_id) REFERENCES checkpoints(run_id,namespace,checkpoint_id));
CREATE TABLE command_receipts(principal_id TEXT NOT NULL, command_id TEXT NOT NULL, request_digest TEXT NOT NULL, result_code INTEGER NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at TEXT NOT NULL, PRIMARY KEY(principal_id,command_id));
CREATE TABLE audit_segments(id TEXT PRIMARY KEY, key_generation TEXT NOT NULL, first_sequence INTEGER NOT NULL, last_sequence INTEGER, prior_tag BLOB NOT NULL, sealed_tag BLOB, retired_at TEXT);
CREATE TABLE audit_events(sequence INTEGER PRIMARY KEY, event_id TEXT NOT NULL UNIQUE, segment_id TEXT NOT NULL REFERENCES audit_segments(id), kind TEXT NOT NULL, entity_id TEXT, minimal_json TEXT NOT NULL CHECK(json_valid(minimal_json)), previous_tag BLOB NOT NULL, tag BLOB NOT NULL, occurred_at TEXT NOT NULL);
CREATE TABLE events(cursor INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL, kind TEXT NOT NULL, summary_json TEXT NOT NULL CHECK(json_valid(summary_json)), occurred_at TEXT NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY, kind TEXT NOT NULL, phase TEXT NOT NULL, subject_version TEXT REFERENCES content_versions(id), expected_revision INTEGER, error_code TEXT, created_at TEXT NOT NULL);
CREATE TABLE backups(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operations(id), manifest_version TEXT REFERENCES content_versions(id), destination_ref TEXT NOT NULL, snapshot_sequence INTEGER NOT NULL, status TEXT NOT NULL, completed_at TEXT, expires_at TEXT);
CREATE TABLE artifact_pins(artifact_version TEXT NOT NULL REFERENCES artifact_versions(id), operation_id TEXT NOT NULL REFERENCES operations(id), PRIMARY KEY(artifact_version,operation_id));
CREATE TABLE deletion_records(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operations(id), opaque_subject_id TEXT NOT NULL, completed_at TEXT, minimal_reason TEXT NOT NULL);
CREATE INDEX actions_run_state ON actions(run_id,state);
CREATE INDEX outcomes_action_time ON outcomes(action_id,occurred_at);
CREATE INDEX events_entity_revision ON events(entity_type,entity_id,revision);
CREATE INDEX artifact_readiness ON artifact_versions(readiness);
CREATE INDEX checkpoint_parent ON checkpoints(run_id,namespace,parent_id);
-- Immutable published records: authorized retention DELETE runs separately after dependency preview.
CREATE TRIGGER content_immutable BEFORE UPDATE ON content_versions BEGIN SELECT RAISE(ABORT,'immutable content version'); END;
CREATE TRIGGER outcome_immutable BEFORE UPDATE ON outcomes BEGIN SELECT RAISE(ABORT,'append correction instead'); END;
CREATE TRIGGER audit_immutable BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'append audit event instead'); END;
CREATE TRIGGER checkpoint_immutable BEFORE UPDATE ON checkpoints BEGIN SELECT RAISE(ABORT,'checkpoint id reused'); END;
